mapper.select:
SELECT COUNT(*) > 0
FROM edu.enrollments e
INNER JOIN edu.teachers t ON t.user_id = e.user_id
WHERE e.course_id = #{courseId}
  AND e.user_id = #{teacherId}

SELECT COUNT(*) > 0
FROM edu.enrollments e
INNER JOIN edu.students s ON s.user_id = e.user_id
WHERE e.course_id = #{courseId}
  AND e.user_id = #{studentId}
